// Closed errno set (SSOT for all three SDKs). Wire spelling is the
// SCREAMING POSIX name (EPERM, EACCES), except EConfig,
// ESecurityViolation, EUnknownKind, EClockRegress, and PathTraversal,
// which keep their mixed-case wire spelling. There is no silent
// fallback: an unrecognized name is not an errno, and no hook boundary
// accepts a bare string errno.
//
// PathTraversal is the one traversal-specific member: a lookup that
// escapes the declared root denies with Action.drop carrying
// Errno.PATH_TRAVERSAL, and the driver maps it to EPERM before it
// surfaces to the guest (the guest never sees a non-POSIX traversal
// errno).
export enum Errno {
  EPERM = "EPERM",
  EACCES = "EACCES",
  ENOENT = "ENOENT",
  EINVAL = "EINVAL",
  ENOSPC = "ENOSPC",
  EROFS = "EROFS",
  ECONNREFUSED = "ECONNREFUSED",
  ENXIO = "ENXIO",
  EWOULDBLOCK = "EWOULDBLOCK",
  EFAULT = "EFAULT",
  EBUSY = "EBUSY",
  EXDEV = "EXDEV",
  EPIPE = "EPIPE",
  ENODATA = "ENODATA",
  EPROTO = "EPROTO",
  EPOLICY = "EPOLICY",
  ETOOLQUOTA = "ETOOLQUOTA",
  EWXVIOLATION = "EWXVIOLATION",
  E_CONFIG = "EConfig",
  E_SECURITY_VIOLATION = "ESecurityViolation",
  E_UNKNOWN_KIND = "EUnknownKind",
  E_CLOCK_REGRESS = "EClockRegress",
  PATH_TRAVERSAL = "PathTraversal",
}

/** Hold primitive for Action.suspend. Deadline is in milliseconds. */
export type SuspendUntil =
  | { deadline: number }
  | { approval: true }
  | { handshake: true };

/** In-place mutation payload, registered per ring. */
export type PatchPayload =
  | { execveMutation: {
      binary: string | null;
      argv: string[] | null;
      setEnv: Record<string, string>;
      unsetEnv: string[];
    } }
  | { fsInode: {
      mode: number;
      uid: number;
      gid: number;
      size: number;
      content: Uint8Array;
    } }
  | { custom: { name: string; cbor: unknown } };

/**
 * The unified action algebra: one enum for every interposer hook
 * return (02-plugin-model #Unified-verdict). Denial is Action.drop;
 * fatal termination is Action.abort; both are actions, never errors.
 *
 * Ring restriction is enforced by the ring trait's return type, not by
 * the enum: onFsWrite accepts only forward | drop | suspend | abort;
 * onFsLookup accepts only pass | drop | suspend | abort | patch. There
 * is no patch on filter rings: the transformed buffer IS the payload.
 */
export type Action =
  | { kind: "pass" }
  | { kind: "forward" }
  | { kind: "drop"; errno: Errno; reason: string }
  | { kind: "suspend"; until: SuspendUntil }
  | { kind: "abort"; reason: string }
  | { kind: "patch"; payload: PatchPayload };

/** Type aliases, not separate enums: the Verdict / FilterAction split
 *  collapses onto Action here. Old call sites keep resolving; new code
 *  writes Action directly. No third alias exists, and a thrown handler
 *  error never carries a policy denial (PluginError-scope pin). */
export type Verdict = Action;
export type FilterAction = Action;
